// libGaugeApp.so - iDrive-7-style gauge screens (engine, driving, fuel and trip, performance, warm-up) as a native
// iDrive "PluginApp" for BMW NBT Evo (ID5 / ID6) and EntryNav2 head units. This file is the PluginApp itself: the
// entry point, the object with its own vtable, onInit / onError / onFinalize, the button actions and the render tick.
// The other modules are listed in app.hpp.
//
// How it works: HmiMain3D loads Plugins/GaugeApp/GaugeApp.manifest at boot. GaugeApp.xml (generated by make_db.py)
// adds a menu row and one HMI state per screen: a background image and image components on top of it, each bound to
// a raImageModel. The app subscribes to the car's CDS properties (cds.cpp), keeps the latest values in g_state and,
// five times a second, sends the PNG data of every image whose picture changed (render.cpp, frames.cpp).
//
// The framework glue (PluginApp constructor, own vtable, Runnable stand-in, pluginAppInfo) is the pattern car-verified
// by NBT-AAD's rhmiapp/nbt_aad_app.cpp (https://github.com/Sq00ky/Supra-iDrive6-Android-Auto) and entry-aad's
// hmiapp/bmw_framework.cpp; the declarations are in bmw_framework.hpp.
#include <dlfcn.h>
#include <new>
#include <stdint.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#ifndef RTLD_DEFAULT
#define RTLD_DEFAULT ((void*)-2)   // QNX value
#endif
#include "app.hpp"

namespace ga {

// ---- the shared state -----------------------------------------------------------------------------------------------
pthread_mutex_t g_dataMutex = PTHREAD_MUTEX_INITIALIZER;
AppState g_state;

AppState::AppState()
    : dirty(true), maxDirty(false), settingsDirty(false), brakeFull(0), visible(kVisUnknown), totalSeen(0),
      subscribedAt(-1), noDataLogged(false) {
    for (int p = 0; p < eng::kPropCount; ++p) { seen[p] = 0; lastOk[p] = false; }
}

void AppState::startRun(long nowMs) {
    gmax = eng::GMax();
    trip.reset(nowMs);
    perf = eng::Perf();
    warm.reset();
    brakeFull = 0;
    visible = kVisUnknown;
    for (int p = 0; p < eng::kPropCount; ++p) { seen[p] = 0; lastOk[p] = false; }
    totalSeen = 0;
    subscribedAt = -1;
    noDataLogged = false;
}

namespace {

bmw::PluginApp* g_app = NULL;                // set in create, cleared in finalize / destroy

// ---- bmw::Runnable stand-in (vtable: offset-to-top, typeinfo, ~D1, ~D0, run), copied from libCoreFramework's own
// vtable so the type info is right. Static objects, so the destructor slots are no-ops. Same technique as NBT-AAD.
struct StandInRunnable { void** vptr; };
void runnableNoop(void*) {}

void initRunnable(StandInRunnable& r, void** vtbl /* 5 slots */, void (*run)(void*)) {
    void** base = reinterpret_cast<void**>(dlsym(RTLD_DEFAULT, "_ZTVN3bmw8RunnableE"));
    if (base) memcpy(vtbl, base, 5 * sizeof(void*));
    else { vtbl[0] = NULL; vtbl[1] = NULL; }
    vtbl[2] = reinterpret_cast<void*>(&runnableNoop);
    vtbl[3] = reinterpret_cast<void*>(&runnableNoop);
    vtbl[4] = reinterpret_cast<void*>(run);
    r.vptr = vtbl + 2;
}

StandInRunnable g_subRunnable;
StandInRunnable g_renderRunnable;
void* g_subVtbl[5];
void* g_renderVtbl[5];

void post(bmw::PluginApp* app, StandInRunnable& r, unsigned ms) {
    app->post(reinterpret_cast<bmw::Runnable*>(&r), ms);
}

// ---- the render tick (every kRenderMs) ------------------------------------------------------------------------------
void renderRun(void* /*self*/) {
    bmw::PluginApp* app = g_app;
    if (!app) return;                                    // finalized: do not post again
    {
        MutexLock lock(g_dataMutex);
        g_state.trip.tick(monoMs(), g_state.cal.factor);
    }
    const FrameSink out = pluginSink(app);
    renderVisible(out);
    diagAnimTick(out);
    saveDueFiles();
    markStableWhenDue();
    bool warnNoData = false;
    {
        MutexLock lock(g_dataMutex);
        if (!g_state.noDataLogged && g_state.subscribedAt >= 0 && g_state.totalSeen == 0 &&
            monoSec() - g_state.subscribedAt >= kNoDataWarnS) {
            g_state.noDataLogged = true;
            warnNoData = true;
        }
    }
    if (warnNoData)
        elog("no CDS value arrived %ld s after subscribing: the car may not publish engine.* / driving.* to plugin "
             "apps, or the subscription failed (see README, 'No data')", kNoDataWarnS);
    post(app, g_renderRunnable, kRenderMs);
}

// ~1.5 s after onInit: every CDS handler, then the render loop.
void subscribeRun(void* /*self*/) {
    bmw::PluginApp* app = g_app;
    if (!app) return;
    subscribeAll(app);
    initRunnable(g_renderRunnable, g_renderVtbl, &renderRun);
    post(app, g_renderRunnable, kRenderMs);
}

// ---- the settings page (hmiState 12, opened from the OPTION menu) ----------------------------------------------------
// One button per setting; each press switches to the next value and redraws the screen (settings.txt is written on
// the next render tick).
void showSettingText(bmw::PluginApp* app, int s) {
    eng::Settings st;
    {
        MutexLock lock(g_dataMutex);
        st = g_state.settings;
    }
    bmw::TextID text(eng::settingText(st, s));
    app->updateModel(eng::ids::kSettingsTextModel + (unsigned)s, text);
}

void onSetting(bmw::PluginApp* app, int s) {
    eng::Settings st;
    {
        MutexLock lock(g_dataMutex);
        eng::cycleSetting(g_state.settings, s);
        st = g_state.settings;
        g_state.dirty = true;
        g_state.settingsDirty = true;
    }
    elog("settings: %s -> %d", eng::settingKey(s), eng::settingValue(st, s));
    showSettingText(app, s);
    const FrameSink out = pluginSink(app);
    if (s == eng::kSetColor) {
        loadColor(st.color);
        invalidateScreens();                             // same frame ids, other pictures: send everything again
        renderView(out, kEverything);
    } else {
        renderView(out, kOnlyChanged);
    }
}

typedef bool (*ActionStub)(void*, const bmw::Parcel&);
template <int S> bool onSettingAction(void* app, const bmw::Parcel&) {
    onSetting(static_cast<bmw::PluginApp*>(app), S);
    return true;
}
const ActionStub kSettingStubs[] = { &onSettingAction<0>, &onSettingAction<1>, &onSettingAction<2>,
                                     &onSettingAction<3>, &onSettingAction<4> };
GA_STATIC_ASSERT(GA_COUNT(kSettingStubs) == eng::kSettingCount, one_stub_per_setting);

// The entry button (raAction): the screen shown last (settings.txt "screen"), opened with its focusEvent.
bool onEntry(void* app, const bmw::Parcel&) {
    int s;
    {
        MutexLock lock(g_dataMutex);
        s = g_state.settings.screen;
    }
    if (s < 0 || s >= eng::ids::kScreenCount) s = eng::kScreenEngine;
    elog("entry button: screen %d (focusEvent %u)", s, eng::ids::kScreenEvent0 + (unsigned)s);
    static_cast<bmw::PluginApp*>(app)->triggerEvent(eng::ids::kScreenEvent0 + (unsigned)s);
    return true;
}

void addAction(bmw::PluginApp* self, unsigned action, ActionStub stub) {
    bmw::ActionDelegate d;
    d.object = self;
    d.stub = stub;
    self->addHandler(action, d);
}

// ---- the app object -------------------------------------------------------------------------------------------------
void* g_vtbl[2 + kVtblSlots];   // [offset-to-top, typeinfo, slots...] copied from bmw::PluginApp's vtable

bool appOnInit(bmw::PluginApp* self) {
    // Action handlers before the base onInit, as entry-aad does.
    addAction(self, eng::ids::kEntryAction, &onEntry);
    for (int s = 0; s < eng::kSettingCount; ++s) addAction(self, eng::ids::kSettingsAction + (unsigned)s, kSettingStubs[s]);
    bool ok = self->onInit();                            // base implementation
    storageStartRun();
    resetMaxima();
    loadSettings();
    loadKept();
    int color;
    {
        MutexLock lock(g_dataMutex);
        g_state.startRun(monoMs());
        color = g_state.settings.color;
    }
    invalidateScreens();
    framesStartRun();
    loadFrames();
    loadColor(color);
    for (int s = 0; s < eng::kSettingCount; ++s) showSettingText(self, s);
    const FrameSink out = pluginSink(self);
    int written = renderView(out, kEverything);          // "--" everywhere until the first CDS values arrive
    sendDiagPictures(out);
    initRunnable(g_subRunnable, g_subVtbl, &subscribeRun);
    post(self, g_subRunnable, kSubscribeDelayMs);
    elog("onInit: base onInit -> %d, %d images written, CDS subscription in %u ms", (int)ok, written,
         kSubscribeDelayMs);
    return ok;
}

void appOnError(bmw::PluginApp* /*self*/, unsigned code, const bmw::BasicString<char>& text) {
    const char* s = text.raw();
    elog("onError %u: %s", code, s ? s : "(null)");
}

void appOnFinalize(bmw::PluginApp* self) {
    elog("onFinalize");
    g_app = NULL;                                        // posted Runnables see this and stop
    bool maxDirty;
    {
        MutexLock lock(g_dataMutex);
        maxDirty = g_state.maxDirty;
    }
    if (maxDirty) saveMaxima();
    saveKept();
    saveSettingsIfDirty();
    self->onFinalize();
}

bmw::PluginApp* createApp(bmw::IDispatcher& dispatcher, const char* name, const bmw::Bundle& params,
                          const bmw::Bundle& config) {
    mkdir(kDataDir, 0755);
    elog("create(name=%s) %s", name ? name : "(null)", ENGINE_APP_VERSION);
    if (fileExists(kDisableA) || fileExists(kDisableB)) { elog("disabled by app.disable"); return NULL; }
    if (g_app) { elog("create: already created"); return NULL; }
    if (!crashGuardAllows()) return NULL;

    void* mem = ::operator new(bmw::kPluginAppStorage);
    memset(mem, 0, bmw::kPluginAppStorage);
    bmw::PluginApp* app = new (mem) bmw::PluginApp(dispatcher, bmw::BasicString<char>(name ? name : "GaugeApp"), 1, 0,
                                                   bmw::RHMI_INTERFACE_VERSION_1, params, config);

    // Own vtable: identical to bmw::PluginApp's, with our onInit / onError / onFinalize (what a C++ subclass would do).
    void** base = *reinterpret_cast<void***>(app);
    memcpy(g_vtbl, base - 2, sizeof(g_vtbl));
    g_vtbl[2 + kSlotOnInit]     = reinterpret_cast<void*>(&appOnInit);
    g_vtbl[2 + kSlotOnError]    = reinterpret_cast<void*>(&appOnError);
    g_vtbl[2 + kSlotOnFinalize] = reinterpret_cast<void*>(&appOnFinalize);
    *reinterpret_cast<void***>(app) = g_vtbl + 2;

    g_app = app;
    elog("create: app %p (PluginApp vtable %p)", (void*)app, (void*)base);
    return app;
}

void destroyApp(void* app) {
    elog("destroy(%p)", app);
    if (!app) return;
    if (app == g_app) g_app = NULL;
    void** vt = *reinterpret_cast<void***>(app);
    reinterpret_cast<void (*)(void*)>(vt[1])(app);       // deleting destructor (PluginApp::~PluginApp + operator delete)
}

__attribute__((constructor)) void libraryLoaded() {
    mkdir(kDataDir, 0755);
    elog("library loaded into pid %d, %s", (int)getpid(), ENGINE_APP_VERSION);
}

} // namespace
} // namespace ga

// ---- entry point looked up by ManagedPluginApp::init (dlsym "pluginAppInfo") ----------------------------------------
extern "C" {
struct EnginePluginAppInfo {
    uint16_t versionMajor;
    uint16_t versionMinor;
    const char* name;
    const char* vendor;
    uint32_t rhmiInterfaceVersion;
    bmw::PluginApp* (*create)(bmw::IDispatcher&, const char*, const bmw::Bundle&, const bmw::Bundle&);
    void (*destroy)(void*);
};
__attribute__((visibility("default"))) EnginePluginAppInfo pluginAppInfo = {
    1, 0, "GAUGE APP", "NBT-ENGINE", 1, &ga::createApp, &ga::destroyApp
};
}
